// DeleteUniqueIndexCache 删除索引存在的缓存
func (n *NpsGoLearnSceneNumRepo) DeleteIndexCache(ctx context.Context, data ...*devices_learn_model.NpsGoLearnSceneNum) error {
	KeyMap := make(map[string]struct{})
	keys := make([]string, 0)
	keys = append(keys, n.cache.Key(CacheNpsGoLearnSceneNumByConditionPrefix))
	for _, item := range data {
		if item != nil {
			KeyMap[n.cache.Key(CacheNpsGoLearnSceneNumByIDPrefix, item.ID)] = struct{}{}
			KeyMap[n.cache.Key(CacheNpsGoLearnSceneNumBySNIDSceneTypePrefix, item.SNID, item.SceneType)] = struct{}{}
			KeyMap[n.cache.Key(CacheNpsGoLearnSceneNumBySNIDPrefix, item.SNID)] = struct{}{}
			KeyMap[n.cache.Key(CacheNpsGoLearnSceneNumBySceneTypePrefix, item.SceneType)] = struct{}{}
		}
	}
	for item := range KeyMap {
		keys = append(keys, item)
	}
	err := n.cache.DelBatch(ctx, keys)
	if err != nil {
		return err
	}
	return nil
}
